INSERT INTO moderation_rubric_versions (
    "Id", "Code", "VersionNo", "Name", "SchemaVersion", "DefinitionJson", "ContentHash", "Status", "Revision",
    "CreatedByUserId", "ActivatedByUserId", "ActivatedAt", "RetiredAt", "CreatedAt", "UpdatedAt", "IsDeleted"
)
VALUES
    (1, 'gray-zone', 'gray-zone-moderation-v1', 'Initial gray-zone rubric', 'gray-zone-rubric-schema-v1', '{"purpose":"Assess safety concerns for human moderation of children\u0027s stories. This is not outline fidelity, readability scoring, rewriting or a final publication decision.","criteria":[{"code":"GZ01","name":"Harmful content","check":"Sexual content, graphic violence, hate, bullying, humiliation or degrading treatment.","context":"Distinguish depiction or condemnation of wrongdoing from endorsement. A story showing bullying and addressing its harm is not automatically unsafe.","levels":{"0":"No concern supported by the supplied text and context.","1":"Mild potential concern; interpretation matters. Explain concrete evidence, not hypothetical possibilities.","2":"Meaningful ambiguity or concern requiring human context review.","3":"Clear evidence of a serious safety concern.","4":"Direct, severe harmful content or encouragement."},"examples":[]},{"code":"GZ02","name":"Dangerous imitable behavior","check":"Dangerous actions children could imitate, especially actions praised or presented without appropriate adult support or protective context.","context":"Read consequences and correction elsewhere in the supplied story. Never invent missing protective scenes. Avoid reproducing actionable dangerous instructions in the explanation.","levels":{"0":"No concern supported by the supplied text and context.","1":"Mild potential concern; interpretation matters. Explain concrete evidence, not hypothetical possibilities.","2":"Meaningful ambiguity or concern requiring human context review.","3":"Clear evidence of a serious safety concern.","4":"Direct, severe harmful content or encouragement."},"examples":[]},{"code":"GZ03","name":"Age suitability","check":"Intensity of frightening, distressing or sensitive descriptions for the requested age band.","context":"Do not flag merely for long sentences, difficult vocabulary, ordinary sadness or age-appropriate conflict. Those are not themselves safety violations.","levels":{"0":"No concern supported by the supplied text and context.","1":"Mild potential concern; interpretation matters. Explain concrete evidence, not hypothetical possibilities.","2":"Meaningful ambiguity or concern requiring human context review.","3":"Clear evidence of a serious safety concern.","4":"Direct, severe harmful content or encouragement."},"examples":[]},{"code":"GZ04","name":"Potentially harmful framing","check":"Narrative framing that normalizes coercion, deception, discrimination, abuse or unsafe behavior as desirable or necessary.","context":"Disagreement, fantasy, a flawed character or a different lesson from an outline is not sufficient. Assess what the whole supplied text actually encourages. Do not impose unsupported cultural stereotypes.","levels":{"0":"No concern supported by the supplied text and context.","1":"Mild potential concern; interpretation matters. Explain concrete evidence, not hypothetical possibilities.","2":"Meaningful ambiguity or concern requiring human context review.","3":"Clear evidence of a serious safety concern.","4":"Direct, severe harmful content or encouragement."},"examples":[]},{"code":"GZ05","name":"Privacy and sensitive data","check":"Disclosure of identifying or sensitive personal information, or encouragement of children to share such information.","context":"A fictional first name alone is not proof of a real identity. Do not invent facts about the child or family. Core hard-rule blocks cannot be overridden.","levels":{"0":"No concern supported by the supplied text and context.","1":"Mild potential concern; interpretation matters. Explain concrete evidence, not hypothetical possibilities.","2":"Meaningful ambiguity or concern requiring human context review.","3":"Clear evidence of a serious safety concern.","4":"Direct, severe harmful content or encouragement."},"examples":[]}]}', '6A53DE20FB99FD92334C53CAD3B39BF0732A40C7795C2E98F10C41EF2A759D5E', 'Draft', 1,
     1, NULL, NULL, NULL, NOW(), NULL, false)
ON CONFLICT DO NOTHING;
